import { tool } from '@langchain/core/tools';
import { FindOrderInputSchema } from './contracts.js';
import { findOrder } from './implementations.js';
export const findOrderTool = tool(findOrder, { name: 'find_order', description: 'Finds an order.', schema: FindOrderInputSchema });

import { createAgent, providerStrategy, SystemMessage } from 'langchain';
import { SupportOutputSchema } from './contracts.js';
import { loadSupportInstruction } from './instructions.js';
import { findOrderTool } from './tools.js';
const MIDDLEWARE = [];
const TOOLS = [findOrderTool];
export const supportAgent = createAgent({ model: 'openai:gpt-4o', name: 'support-runtime', systemPrompt: new SystemMessage(loadSupportInstruction()), responseFormat: providerStrategy({ schema: SupportOutputSchema, strict: true }), middleware: MIDDLEWARE, tools: TOOLS });
